1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="UTF-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=no">
6	<title>Heavy Hitters â€” Boxing</title>
7	<style>
8	*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
9	html,body{height:100%;background:#0a0a0a;color:#f0e6d2;font-family:'Segoe UI',system-ui,sans-serif;overflow:hidden;user-select:none;-webkit-user-select:none}
10	
11	#wrap{position:fixed;inset:0;display:flex;align-items:center;justify-content:center}
12	canvas{display:block;background:#1a0d0d;image-rendering:pixelated;box-shadow:0 0 0 4px #2c2c2c, 0 12px 60px rgba(0,0,0,.8)}
13	
14	/* â”€â”€ HUD overlay screens â”€â”€ */
15	.screen{position:absolute;inset:0;display:none;flex-direction:column;align-items:center;justify-content:center;gap:18px;background:rgba(0,0,0,.78);backdrop-filter:blur(6px);z-index:10;color:#ffd700;text-shadow:0 2px 8px #000;text-align:center;padding:24px}
16	.screen.active{display:flex}
17	.screen h1{font-size:64px;letter-spacing:4px;font-weight:900;color:#ffd700;text-shadow:0 4px 0 #6b1a00, 0 6px 20px rgba(0,0,0,.8)}
18	.screen h2{font-size:28px;letter-spacing:2px;color:#ff6b6b}
19	.screen p{font-size:15px;color:#cfc8b8;line-height:1.7;max-width:520px}
20	.screen .btn{background:linear-gradient(180deg,#ffd700,#c89a00);color:#1a0d0d;border:0;font-weight:900;font-size:18px;letter-spacing:2px;padding:14px 36px;border-radius:8px;cursor:pointer;box-shadow:0 4px 0 #7a5e00, 0 8px 16px rgba(0,0,0,.5);transition:transform .12s ease}
21	.screen .btn:hover{transform:translateY(-2px)}
22	.screen .btn:active{transform:translateY(2px);box-shadow:0 2px 0 #7a5e00}
23	.controls{font-size:13px;color:#a8a08a;margin-top:8px}
24	.controls b{color:#ffd700}
25	.controls span{display:inline-block;background:rgba(255,215,0,.12);border:1px solid rgba(255,215,0,.4);border-radius:4px;padding:2px 8px;margin:2px 4px;font-weight:700;color:#ffd700;font-family:Consolas,monospace}
26	
27	/* â”€â”€ Touch controls (mobile) â”€â”€ */
28	#touch-controls{position:absolute;inset:auto 0 0 0;height:0;display:none;z-index:5;pointer-events:none}
29	.touch-pad{position:fixed;bottom:18px;width:120px;height:120px;pointer-events:auto;display:grid;grid-template-columns:repeat(3,1fr);grid-template-rows:repeat(3,1fr);gap:4px}
30	.touch-pad.left{left:18px}
31	.touch-pad.right{right:18px}
32	.touch-btn{background:rgba(0,0,0,.55);border:2px solid rgba(255,215,0,.55);border-radius:50%;color:#ffd700;font-weight:900;font-size:14px;display:flex;align-items:center;justify-content:center;user-select:none;-webkit-user-select:none;-webkit-tap-highlight-color:transparent}
33	.touch-btn:active{background:rgba(255,215,0,.35);color:#1a0d0d}
34	.touch-btn.empty{background:transparent;border:none}
35	@media (pointer:coarse), (max-width:900px) { #touch-controls{display:block} }
36	</style>
37	</head>
38	<body>
39	
40	<div id="wrap"><canvas id="game" width="1000" height="600"></canvas>
41	
42	<div class="screen active" id="screen-title">
43	  <h1>HEAVY HITTERS</h1>
44	  <h2>â˜… Round 1 â˜…</h2>
45	  <p>Three rounds. Three minutes apiece. Drop your opponent or win the bell on points. The crowd is hungry.</p>
46	  <button class="btn" id="btn-fight">FIGHT</button>
47	  <div class="controls">
48	    <div><b>Move:</b> <span>A</span><span>D</span> &nbsp; <b>Approach/Backstep:</b> <span>W</span><span>S</span></div>
49	    <div><b>Jab:</b> <span>J</span> &nbsp; <b>Hook:</b> <span>K</span> &nbsp; <b>Uppercut:</b> <span>L</span> &nbsp; <b>Block:</b> <span>SPACE</span></div>
50	  </div>
51	</div>
52	
53	<div class="screen" id="screen-end">
54	  <h1 id="end-title">VICTORY</h1>
55	  <h2 id="end-sub">By KO in Round 1 Â· 0:42</h2>
56	  <p id="end-stats"></p>
57	  <button class="btn" id="btn-rematch">REMATCH</button>
58	</div>
59	
60	<div id="touch-controls">
61	  <div class="touch-pad left">
62	    <span class="touch-btn empty"></span><span class="touch-btn" data-tk="w">â–²</span><span class="touch-btn empty"></span>
63	    <span class="touch-btn" data-tk="a">â—€</span><span class="touch-btn empty"></span><span class="touch-btn" data-tk="d">â–¶</span>
64	    <span class="touch-btn empty"></span><span class="touch-btn" data-tk="s">â–¼</span><span class="touch-btn empty"></span>
65	  </div>
66	  <div class="touch-pad right">
67	    <span class="touch-btn empty"></span><span class="touch-btn" data-tk="j">JAB</span><span class="touch-btn empty"></span>
68	    <span class="touch-btn" data-tk=" ">BLK</span><span class="touch-btn" data-tk="k">HK</span><span class="touch-btn" data-tk="l">UP</span>
69	    <span class="touch-btn empty"></span><span class="touch-btn empty"></span><span class="touch-btn empty"></span>
70	  </div>
71	</div>
72	</div>
73	
74	<script>
75	'use strict';
76	
77	const W = 1000, H = 600;
78	const FLOOR_Y = 470;     // canvas y where boxers' feet sit
79	const RING_LEFT = 110;
80	const RING_RIGHT = W - 110;
81	
82	const canvas = document.getElementById('game');
83	const ctx = canvas.getContext('2d');
84	
85	function fitCanvas(){
86	  const dpr = Math.min(window.devicePixelRatio || 1, 2);
87	  const wrap = document.getElementById('wrap');
88	  const scale = Math.min(wrap.clientWidth / W, wrap.clientHeight / H);
89	  canvas.style.width  = (W * scale) + 'px';
90	  canvas.style.height = (H * scale) + 'px';
91	  canvas.width  = W * dpr;
92	  canvas.height = H * dpr;
93	  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
94	  ctx.imageSmoothingEnabled = false;
95	}
96	window.addEventListener('resize', fitCanvas);
97	fitCanvas();
98	
99	// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
100	//  Web Audio (simple synth hit / bell sounds)
101	// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
102	let audioCtx = null;
103	function ensureAudio(){
104	  if (!audioCtx){
105	    try { audioCtx = new (window.AudioContext || window.webkitAudioContext)(); }
106	    catch(e){ audioCtx = null; }
107	  }
108	  if (audioCtx && audioCtx.state === 'suspended') audioCtx.resume();
109	}
110	function playTone({freq=200, dur=0.08, type='sine', vol=0.3, attack=0.005, decay=0.05}){
111	  if (!audioCtx) return;
112	  const t = audioCtx.currentTime;
113	  const o = audioCtx.createOscillator();
114	  const g = audioCtx.createGain();
115	  o.type = type; o.frequency.setValueAtTime(freq, t);
116	  g.gain.setValueAtTime(0, t);
117	  g.gain.linearRampToValueAtTime(vol, t + attack);
118	  g.gain.exponentialRampToValueAtTime(0.001, t + dur);
119	  o.connect(g); g.connect(audioCtx.destination);
120	  o.start(t); o.stop(t + dur);
121	}
122	function playHit(power){
123	  // power: 1=jab, 2=hook, 3=uppercut
124	  ensureAudio();
125	  if (!audioCtx) return;
126	  if (power === 1){ playTone({ freq: 400, dur: 0.06, type: 'square', vol: 0.18 }); }
127	  else if (power === 2){ playTone({ freq: 220, dur: 0.10, type: 'square', vol: 0.25 }); playTone({ freq: 110, dur: 0.12, type: 'sine', vol: 0.18 }); }
128	  else { playTone({ freq: 90, dur: 0.18, type: 'sawtooth', vol: 0.3 }); playTone({ freq: 50, dur: 0.20, type: 'sine', vol: 0.22 }); }
129	}
130	function playBlock(){
131	  ensureAudio();
132	  playTone({ freq: 700, dur: 0.05, type: 'square', vol: 0.12 });
133	}
134	function playBell(){
135	  ensureAudio();
136	  for (const f of [880, 1318, 1760]){
137	    playTone({ freq: f, dur: 1.2, type: 'sine', vol: 0.16, attack: 0.005 });
138	  }
139	}
140	
141	// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
142	//  Game state
143	// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
144	const PUNCH = {
145	  jab:      { dmg: 6,  stam: 5,  range: 78, windup: 0.06, active: 0.06, recover: 0.18, knockback: 4 },
146	  hook:     { dmg: 12, stam: 12, range: 70, windup: 0.14, active: 0.08, recover: 0.28, knockback: 8 },
147	  uppercut: { dmg: 20, stam: 20, range: 60, windup: 0.22, active: 0.10, recover: 0.36, knockback: 14 },
148	};
149	
150	const ROUND_LEN = 60; // seconds
151	const TOTAL_ROUNDS = 3;
152	
153	let state = 'title';      // 'title' | 'fight' | 'roundover' | 'end'
154	let round = 1;
155	let roundClock = ROUND_LEN;
156	let roundResult = '';     // text shown on round-end overlay
157	let scorePlayer = 0, scoreCpu = 0; // rounds won
158	let knockdownsPlayer = 0, knockdownsCpu = 0;
159	let endTitle = '', endSub = '';
160	
161	// Slow motion when a KO punch lands
162	let slowmoT = 0;
163	let screenFlash = 0;
164	let screenShake = 0;
165	
166	// Hit-text bursts (pow/bam)
167	const hits = [];
168	
169	function makeBoxer(opts){
170	  return {
171	    name: opts.name,
172	    isPlayer: !!opts.isPlayer,
173	    x: opts.x,
174	    y: FLOOR_Y,
175	    vx: 0,
176	    facing: opts.facing || 1, // +1 = facing right, -1 = facing left
177	    hp: 100, maxHp: 100,
178	    stamina: 100, maxStam: 100,
179	    color: opts.color,
180	    trunks: opts.trunks,
181	    skin: opts.skin || '#d6a26b',
182	    action: 'idle',          // 'idle' | 'jab' | 'hook' | 'uppercut' | 'block' | 'hit' | 'ko'
183	    actionT: 0,              // time elapsed in current action
184	    actionDur: 0,            // total duration of current action
185	    hitFrameDone: false,     // already-applied damage on this active punch
186	    moveX: 0,
187	    flinch: 0,               // visual flinch timer
188	    bob: 0,
189	    aiTimer: 0,
190	    aiState: 'idle',
191	    aiAggression: 0.5,
192	    aiReaction: 0.4,
193	  };
194	}
195	
196	let player, cpu;
197	
198	function resetMatch(){
199	  state = 'fight';
200	  round = 1;
201	  roundClock = ROUND_LEN;
202	  scorePlayer = 0; scoreCpu = 0;
203	  knockdownsPlayer = 0; knockdownsCpu = 0;
204	  hits.length = 0;
205	  setupRound();
206	  hideScreen('screen-title');
207	  hideScreen('screen-end');
208	  playBell();
209	}
210	
211	function setupRound(){
212	  player = makeBoxer({ name:'YOU', isPlayer: true, x: 320, facing:  1, color:'#7d2424', trunks:'#cc0000', skin:'#d6a26b' });
213	  cpu    = makeBoxer({ name:'BRUNO', x: 680, facing: -1, color:'#1f3d6e', trunks:'#0066ff', skin:'#c08550' });
214	  cpu.aiAggression = 0.45 + round*0.12;
215	  cpu.aiReaction = 0.35 + round*0.10;
216	  roundClock = ROUND_LEN;
217	}
218	
219	// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
220	//  Input
221	// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
222	const keys = {};
223	window.addEventListener('keydown', e => {
224	  ensureAudio();
225	  const k = e.key.toLowerCase();
226	  if (['w','a','s','d','j','k','l',' '].includes(k)) e.preventDefault();
227	  keys[k] = true;
228	});
229	window.addEventListener('keyup', e => { keys[e.key.toLowerCase()] = false; });
230	
231	// Touch buttons
232	document.querySelectorAll('#touch-controls .touch-btn[data-tk]').forEach(btn => {
233	  const tk = btn.dataset.tk;
234	  btn.addEventListener('touchstart', e => { e.preventDefault(); ensureAudio(); keys[tk] = true; });
235	  btn.addEventListener('touchend',   e => { e.preventDefault(); keys[tk] = false; });
236	  btn.addEventListener('touchcancel',e => { keys[tk] = false; });
237	});
238	
239	// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
240	//  Boxer logic
241	// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
242	function startAction(b, kind){
243	  if (b.hp <= 0) return;
244	  if (b.action === 'ko') return;
245	  if (b.action !== 'idle' && b.action !== 'block') return; // can't interrupt
246	  if (kind in PUNCH){
247	    const p = PUNCH[kind];
248	    const stamReq = p.stam * (b.stamina < 25 ? 1.0 : 1.0);
249	    if (b.stamina < p.stam * 0.5) return; // too gassed
250	    b.stamina = Math.max(0, b.stamina - p.stam);
251	    b.action = kind;
252	    b.actionT = 0;
253	    b.actionDur = p.windup + p.active + p.recover;
254	    b.hitFrameDone = false;
255	  } else if (kind === 'block'){
256	    b.action = 'block';
257	    b.actionT = 0;
258	    b.actionDur = 0.0; // hold-to-block
259	  }
260	}
261	
262	function endAction(b){
263	  b.action = 'idle';
264	  b.actionT = 0;
265	}
266	
267	function takeHit(target, source, kind){
268	  const p = PUNCH[kind];
269	  const blocked = (target.action === 'block');
270	  let dmg = p.dmg;
271	  if (blocked){
272	    dmg = Math.round(dmg * 0.18);
273	    target.stamina = Math.max(0, target.stamina - p.stam * 0.6);
274	    playBlock();
275	    pushHitText(target.x, target.y - 100, 'BLOCK', '#9fdcff');
276	  } else {
277	    if (kind === 'uppercut') dmg += 4;
278	    target.flinch = 0.35;
279	    if (target.action !== 'ko') target.action = 'hit';
280	    target.actionT = 0;
281	    target.actionDur = p.windup + 0.05;
282	    target.x += (target.x < source.x ? -1 : 1) * p.knockback * (blocked ? 0.3 : 1);
283	    playHit(kind === 'jab' ? 1 : kind === 'hook' ? 2 : 3);
284	    const word = kind === 'jab' ? 'POW' : kind === 'hook' ? 'BAM' : 'BOOM';
285	    const col = kind === 'jab' ? '#ffd700' : kind === 'hook' ? '#ff7a00' : '#ff3838';
286	    pushHitText(target.x, target.y - 110, word, col);
287	    if (kind === 'uppercut') screenFlash = 0.12;
288	    screenShake = Math.max(screenShake, kind === 'jab' ? 2 : kind === 'hook' ? 4 : 7);
289	  }
290	  target.hp -= dmg;
291	  if (target.hp <= 0){
292	    target.hp = 0;
293	    target.action = 'ko';
294	    target.actionT = 0;
295	    target.actionDur = 1.6;
296	    slowmoT = 1.5;
297	    screenFlash = 0.2;
298	    if (target.isPlayer) knockdownsPlayer++; else knockdownsCpu++;
299	  }
300	}
301	
302	function pushHitText(x, y, txt, color){
303	  hits.push({ x, y, txt, color, t: 0, life: 0.7, vy: -40 - Math.random()*30 });
304	}
305	
306	// Punch hit testing â€” during the "active" frame, check distance + facing
307	function checkPunchHit(attacker, defender){
308	  if (!(attacker.action in PUNCH)) return;
309	  const p = PUNCH[attacker.action];
310	  const elapsed = attacker.actionT;
311	  const inActive = (elapsed >= p.windup && elapsed <= p.windup + p.active);
312	  if (!inActive) return;
313	  if (attacker.hitFrameDone) return;
314	  // Range check: distance between centers, and attacker must be facing defender
315	  const dx = defender.x - attacker.x;
316	  const dist = Math.abs(dx);
317	  if (dist > p.range) return;
318	  // Must face the defender
319	  if (attacker.facing > 0 && dx < 0) return;
320	  if (attacker.facing < 0 && dx > 0) return;
321	  attacker.hitFrameDone = true;
322	  takeHit(defender, attacker, attacker.action);
323	}
324	
325	// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
326	//  Update tick
327	// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
328	function tickPlayer(b, dt){
329	  // Auto-face the opponent
330	  b.facing = (cpu.x > b.x) ? 1 : -1;
331	  // Movement when no action limits
332	  let mx = 0;
333	  if (keys['a']) mx -= 1;
334	  if (keys['d']) mx += 1;
335	  if (keys['w']) mx += b.facing * 0.6;
336	  if (keys['s']) mx -= b.facing * 0.6;
337	  const speed = (b.action === 'idle' || b.action === 'block') ? 240 : 60;
338	  if (b.action !== 'ko' && b.action !== 'hit'){
339	    b.x += mx * speed * dt;
340	  }
341	  b.x = Math.max(RING_LEFT + 30, Math.min(RING_RIGHT - 30, b.x));
342	  // Block toggling
343	  if (b.action === 'block' && !keys[' ']) endAction(b);
344	  // Action triggers
345	  if (b.action === 'idle'){
346	    if (keys[' '])      startAction(b, 'block');
347	    else if (keys['j']) startAction(b, 'jab');
348	    else if (keys['k']) startAction(b, 'hook');
349	    else if (keys['l']) startAction(b, 'uppercut');
350	  }
351	  tickAction(b, dt);
352	}
353	
354	function tickAction(b, dt){
355	  if (b.action === 'ko'){
356	    b.actionT += dt;
357	    return;
358	  }
359	  if (b.action === 'hit'){
360	    b.actionT += dt;
361	    if (b.actionT >= b.actionDur) endAction(b);
362	    return;
363	  }
364	  if (b.action === 'block'){
365	    // drain stamina slowly while blocking
366	    b.stamina = Math.max(0, b.stamina - 4 * dt);
367	    return;
368	  }
369	  if (b.action in PUNCH){
370	    b.actionT += dt;
371	    // hit detection runs during active window â€” handled in main update
372	    if (b.actionT >= b.actionDur) endAction(b);
373	  }
374	  // Stamina regen when idle
375	  if (b.action === 'idle' && b.stamina < b.maxStam){
376	    b.stamina = Math.min(b.maxStam, b.stamina + 18 * dt);
377	  }
378	  // Flinch decay
379	  if (b.flinch > 0) b.flinch = Math.max(0, b.flinch - dt);
380	}
381	
382	function tickCpu(c, dt){
383	  c.facing = (player.x < c.x) ? -1 : 1;
384	  c.aiTimer -= dt;
385	  const dx = player.x - c.x;
386	  const dist = Math.abs(dx);
387	
388	  // React to incoming heavy punches by blocking
389	  const playerThreatening = (player.action === 'hook' || player.action === 'uppercut') && player.actionT < PUNCH[player.action].windup;
390	  if (playerThreatening && dist < 110 && Math.random() < c.aiReaction * dt * 60){
