415	            else if (Math.random() < 0.6) c.aiState = 'hook';
416	            else c.aiState = 'uppercut';
417	          } else if (r < 0.85){
418	            c.aiState = 'sidestep';
419	          } else {
420	            c.aiState = 'block-tactical';
421	          }
422	        }
423	      }
424	    }
