426	    const speed = 180;
427	    if (c.aiState === 'advance'){
428	      c.x += -c.facing * speed * dt; // move toward player (since facing player)
429	      // Actually: player is at dx from c. If dx<0, player to left â†’ move left.
430	      // facing is sign of (player.x - c.x). To move toward player, move in +facing? No:
431	      // facing=+1 means player to right. To advance, move +1. We had c.x += -c.facing => wrong.
432	      // Fix:
433	    } else if (c.aiState === 'retreat'){
434	      // away from player
435	    } else if (c.aiState === 'sidestep'){
436	      // small lateral motion
437	    }
438	  }
439	
440	  // Simpler movement model: replace block above with this
441	  if (c.action === 'idle'){
442	    let cmx = 0;
443	    if (c.aiState === 'advance') cmx = (dx > 0 ? 1 : -1);
444	    else if (c.aiState === 'retreat') cmx = (dx > 0 ? -1 : 1);
445	    else if (c.aiState === 'sidestep') cmx = (dx > 0 ? -0.3 : 0.3);
446	    else if (c.aiState === 'jab')      { startAction(c, 'jab'); cmx = 0; }
447	    else if (c.aiState === 'hook')     { startAction(c, 'hook'); cmx = 0; }
448	    else if (c.aiState === 'uppercut') { startAction(c, 'uppercut'); cmx = 0; }
449	    else if (c.aiState === 'block-tactical'){ startAction(c, 'block'); cmx = 0; }
450	    const speed = 170;
451	    c.x += cmx * speed * dt;
452	    c.x = Math.max(RING_LEFT + 30, Math.min(RING_RIGHT - 30, c.x));
453	  }
