461	let lastT = performance.now();
462	function loop(now){
463	  requestAnimationFrame(loop);
464	  let dt = (now - lastT) / 1000;
465	  lastT = now;
466	  if (dt > 0.1) dt = 0.1;
467	
468	  // Slow motion scale
469	  if (slowmoT > 0){
470	    slowmoT -= dt;
471	    dt *= 0.32;
472	  }
473	
474	  if (state === 'fight'){
475	    update(dt);
476	  }
477	  // hit-text decay always (so they fade out on screens too)
478	  for (let i = hits.length - 1; i >= 0; i--){
479	    const h = hits[i];
480	    h.t += dt; h.y += h.vy * dt; h.vy += 60 * dt;
481	    if (h.t >= h.life) hits.splice(i, 1);
482	  }
483	  if (screenFlash > 0) screenFlash = Math.max(0, screenFlash - dt * 1.5);
484	  if (screenShake > 0) screenShake = Math.max(0, screenShake - dt * 18);
485	
486	  draw();
487	}
