492	  tickCpu(cpu, dt);
493	  checkPunchHit(player, cpu);
494	  checkPunchHit(cpu, player);
495	
496	  // Round end conditions
497	  if (player.hp <= 0 || cpu.hp <= 0){
498	    setTimeout(roundEnd, 1500);
499	    state = 'roundover';
500	  } else if (roundClock <= 0){
501	    roundClock = 0;
502	    setTimeout(roundEnd, 800);
503	    state = 'roundover';
504	  }
