510	  if (player.hp <= 0) winner = 'cpu';
511	  else if (cpu.hp <= 0) winner = 'player';
512	  else if (player.hp > cpu.hp) winner = 'player';
513	  else if (cpu.hp > player.hp) winner = 'cpu';
514	
515	  if (winner === 'player') scorePlayer++;
516	  else if (winner === 'cpu') scoreCpu++;
