732	function drawArms(b){
733	  // Glove color matches trunks accent
734	  const glove = b.trunks === '#cc0000' ? '#ff3838' : '#3da2ff';
735	  const stroke = '#1a0d0d';
736	  const action = b.action;
737	  const t = b.actionT;
738	  let leadExt = 0, rearExt = 0;
739	  let leadAng = 0, rearAng = 0;
740	  let leadY = 0, rearY = 0;
741	
742	  if (action === 'jab'){
743	    const p = PUNCH.jab;
744	    if (t < p.windup) { leadExt = (t / p.windup) * 30; }
745	    else if (t < p.windup + p.active) { leadExt = 30 + 20; }
746	    else { const r = (t - p.windup - p.active) / p.recover; leadExt = 50 * (1 - r); }
747	  } else if (action === 'hook'){
748	    const p = PUNCH.hook;
749	    if (t < p.windup){ rearAng = -((t / p.windup) * 0.8); rearExt = 8; }
750	    else if (t < p.windup + p.active){ rearAng = 0.4; rearExt = 50; }
751	    else { const r = (t - p.windup - p.active) / p.recover; rearAng = 0.4 * (1 - r); rearExt = 50 * (1 - r); }
752	  } else if (action === 'uppercut'){
753	    const p = PUNCH.uppercut;
754	    if (t < p.windup){ rearY = -(t / p.windup) * 18; rearExt = 5; }
755	    else if (t < p.windup + p.active){ rearY = -28; rearExt = 38; }
756	    else { const r = (t - p.windup - p.active) / p.recover; rearY = -28 * (1 - r); rearExt = 38 * (1 - r); }
757	  } else if (action === 'block'){
758	    leadExt = 6; rearExt = 6;
759	    leadY = -16; rearY = -16;
760	    leadAng = 0.4; rearAng = -0.4;
761	  } else if (action === 'hit'){
762	    leadExt = -4; rearExt = -4;
763	    leadY = 6; rearY = 6;
764	  }
765	
766	  // Rear arm (back arm) â€” drawn first so lead arm is in front
767	  ctx.save();
768	  ctx.translate(-10, -75 + rearY);
769	  ctx.rotate(rearAng);
770	  ctx.fillStyle = '#d6a26b';
771	  ctx.fillRect(0, -6, 14 + rearExt, 12);
772	  ctx.fillStyle = glove;
773	  ctx.beginPath();
774	  ctx.arc(14 + rearExt, 0, 10, 0, Math.PI*2);
775	  ctx.fill();
776	  ctx.strokeStyle = stroke; ctx.lineWidth = 1.5; ctx.stroke();
777	  ctx.restore();
778	
779	  // Lead arm
780	  ctx.save();
781	  ctx.translate(8, -78 + leadY);
782	  ctx.rotate(leadAng);
783	  ctx.fillStyle = '#d6a26b';
784	  ctx.fillRect(0, -6, 14 + leadExt, 12);
785	  ctx.fillStyle = glove;
786	  ctx.beginPath();
787	  ctx.arc(14 + leadExt, 0, 11, 0, Math.PI*2);
788	  ctx.fill();
789	  ctx.strokeStyle = stroke; ctx.lineWidth = 1.5; ctx.stroke();
790	  // Glove highlight
791	  ctx.fillStyle = 'rgba(255,255,255,.35)';
792	  ctx.beginPath();
793	  ctx.arc(14 + leadExt - 3, -3, 3, 0, Math.PI*2);
794	  ctx.fill();
795	  ctx.restore();
796	}
