  const crouchDrop = bend * 16; // hip drops up to 16px when crouching

  // Foot X swing for stepping animation
  const stepAmt = 9;
  const leftFootDX  =  Math.sin(b.legPhase * Math.PI * 2) * stepAmt;
  const rightFootDX =  Math.sin(b.legPhase * Math.PI * 2 + Math.PI) * stepAmt;

  ctx.save();
  ctx.translate(x, y - flinchY - bobY);
  if (koProg > 0){
    ctx.translate(0, koProg * 30);
    ctx.rotate(f * koProg * 0.9);
  }
  ctx.scale(f, 1);

  // Shadow
  ctx.fillStyle = 'rgba(0,0,0,.45)';
  ctx.beginPath();
  ctx.ellipse(0, 4, 30, 6, 0, 0, Math.PI*2);
  ctx.fill();

  // â”€â”€ Legs with bent knees + stepping feet â”€â”€
  const hipY      = -38 + crouchDrop; // hip drops as boxer crouches
  const footY     = 0;                // feet always on floor
  const kneeY     = (hipY + footY) / 2;
  const leftKneeX  = -9 - bend * 13;  // knees splay outward when bent
  const rightKneeX =  9 + bend * 13;

  drawLegSegs(-9, hipY, leftKneeX, kneeY, -9 + leftFootDX, footY, 12, b.trunks);
  drawLegSegs( 9, hipY, rightKneeX, kneeY,  9 + rightFootDX, footY, 12, b.trunks);

  // Knee caps (flesh-toned dots at joint)
  ctx.fillStyle = b.skin;
  ctx.beginPath(); ctx.arc(leftKneeX, kneeY, 5, 0, Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.arc(rightKneeX, kneeY, 5, 0, Math.PI*2); ctx.fill();

  // Boots (move with feet)
  ctx.fillStyle = '#1a1a1a';
  ctx.fillRect(-9 + leftFootDX  - 11, footY - 5, 22, 5);
  ctx.fillRect( 9 + rightFootDX - 11, footY - 5, 22, 5);

  // Trunks waistband (descends with crouch)
  ctx.fillStyle = '#ffd700';
  ctx.fillRect(-22, hipY - 6, 44, 8);

  // Torso (relative to hip)
  ctx.fillStyle = b.skin;
  ctx.fillRect(-22, hipY - 50, 44, 50);
  // Chest shadow
  ctx.fillStyle = 'rgba(0,0,0,.18)';
  ctx.fillRect(-22, hipY - 50, 44, 6);

  // Head + face (relative to hip)
  const headCY = hipY - 68;

