  let leadAng = 0, rearAng = 0;
  let leadY = 0, rearY = 0;

  if (action === 'jab'){
    const p = PUNCH.jab;
    if (t < p.windup) { leadExt = (t / p.windup) * 30; }
    else if (t < p.windup + p.active) { leadExt = 30 + 20; }
    else { const r = (t - p.windup - p.active) / p.recover; leadExt = 50 * (1 - r); }
  } else if (action === 'hook'){
    const p = PUNCH.hook;
    if (t < p.windup){ rearAng = -((t / p.windup) * 0.8); rearExt = 8; }
    else if (t < p.windup + p.active){ rearAng = 0.4; rearExt = 50; }
    else { const r = (t - p.windup - p.active) / p.recover; rearAng = 0.4 * (1 - r); rearExt = 50 * (1 - r); }
  } else if (action === 'uppercut'){
    const p = PUNCH.uppercut;
    if (t < p.windup){ rearY = -(t / p.windup) * 18; rearExt = 5; }
    else if (t < p.windup + p.active){ rearY = -28; rearExt = 38; }
    else { const r = (t - p.windup - p.active) / p.recover; rearY = -28 * (1 - r); rearExt = 38 * (1 - r); }
  } else if (action === 'block'){
    leadExt = 6; rearExt = 6;
    leadY = -16; rearY = -16;
    leadAng = 0.4; rearAng = -0.4;
  } else if (action === 'hit'){
    leadExt = -4; rearExt = -4;
    leadY = 6; rearY = 6;
  }

  // Rear arm (back arm) â€” drawn first so lead arm is in front
  ctx.save();
  ctx.translate(-10, -75 + rearY + crouchDrop);
  ctx.rotate(rearAng);
  ctx.fillStyle = '#d6a26b';
  ctx.fillRect(0, -6, 14 + rearExt, 12);
  ctx.fillStyle = glove;
  ctx.beginPath();
  ctx.arc(14 + rearExt, 0, 10, 0, Math.PI*2);
  ctx.fill();
  ctx.strokeStyle = stroke; ctx.lineWidth = 1.5; ctx.stroke();
  ctx.restore();

  // Lead arm
  ctx.save();
  ctx.translate(8, -78 + leadY + crouchDrop);
  ctx.rotate(leadAng);
  ctx.fillStyle = '#d6a26b';
  ctx.fillRect(0, -6, 14 + leadExt, 12);
  ctx.fillStyle = glove;
  ctx.beginPath();
  ctx.arc(14 + leadExt, 0, 11, 0, Math.PI*2);
  ctx.fill();
  ctx.strokeStyle = stroke; ctx.lineWidth = 1.5; ctx.stroke();
  // Glove highlight
  ctx.fillStyle = 'rgba(255,255,255,.35)';
  ctx.beginPath();
  ctx.arc(14 + leadExt - 3, -3, 3, 0, Math.PI*2);
  ctx.fill();
  ctx.restore();
}

function drawHits(){
  for (const h of hits){
    const a = 1 - (h.t / h.life);
    const scale = 1 + (1 - a) * 0.8;
    ctx.save();
    ctx.translate(h.x, h.y);
    ctx.scale(scale, scale);
    ctx.font = 'bold 36px Arial Black, sans-serif';
    ctx.textAlign = 'center';
    ctx.lineWidth = 4;
    ctx.strokeStyle = 'rgba(0,0,0,' + a + ')';
    ctx.fillStyle = h.color.replace(')', ',' + a + ')').replace('rgb','rgba');
    if (!h.color.startsWith('rgb')){
      // hex colors â€” use globalAlpha
      ctx.globalAlpha = a;
      ctx.fillStyle = h.color;
    }
    ctx.strokeText(h.txt, 0, 0);
    ctx.fillText(h.txt, 0, 0);
    ctx.restore();
  }
